package dev.repodoc;import java.util.*;public class ScoreEngineTest{public static void main(String[]a){var c=Cases.byId("tenant-leak");var perfect=ScoreEngine.score(c,new HashSet<>(c.gold()));assert perfect.score()==100;var noisy=ScoreEngine.score(c,new HashSet<>(List.of("bola","404","async")));assert noisy.precision()<1;assert noisy.score()<100;var none=ScoreEngine.score(c,Set.of());assert none.score()==0;System.out.println("ScoreEngine tests passed");}}